Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Oni są na prostej drodze od swego Pana i oni są szczęśliwi. 2:5; 31:5
- = O dzieciach Izraela, wspominajcie Moją łaskę, którą was obdarzyłem, i że was wywyższyłem ponad światy (ludy). 2:47; 2:122
- = To był naród, który przeminął. Jemu przypada to, co zarobił, a wam przypada to, co zarobiliście. I nie będziecie pytani o to, co oni czynili. 2:134; 2:141
- = Będą tam przebywać na wieki; kara nie będzie im złagodzona i nie będą mieli wytchnienia. 2:162; 3:88
- = Z wyjątkiem tych, którzy po tym pokutują i poprawią się. Zaprawdę, Allah jest Przebaczający, Litościwy. 3:89; 24:5
- = A ci, którzy nie uwierzyli i zaprzeczali Naszym znakom – oni są mieszkańcami Piekła. 5:10; 5:86
- = I nie przychodzi do nich żaden znak ze znaków ich Pana, aby się od niego nie odwrócili. 6:4; 36:46
- = I już przed tobą wyszydzano posłańców, ale tych, którzy szydzili, spotkało to, z czego się naśmiewali. 6:10; 21:41
- = Powiedz: "Boję się, jeśli będę nieposłuszny mojemu Panu, kary Dnia Wielkiego." 6:15; 39:13
- = I pochwyciło ich trzęsienie ziemi, i pozostali w swoich domach martwi, twarzami do ziemi. 7:78; 7:91
- = I rzucił swoją laskę, a oto stała się widocznym wężem. 7:107; 26:32
- = I wyciągnął swoją rękę, a oto stała się biała (lśniąca) dla patrzących. 7:108; 26:33
- = Powiedzieli: "Uwierzyliśmy w Pana światów." 7:121; 26:47
- = Pana Mojżesza i Aarona. 7:122; 26:48
- = I dam im zwłokę. Zaprawdę, mój plan jest mocny. 7:183; 68:45
- = On jest Tym, który posłał Swego Posłańca z drogowskazem i religią prawdy, aby ją wywyższyć ponad wszystkie religie, nawet jeśli wieloboganie nienawidzą. 9:33; 61:9
- = O Proroku, walcz z niewiernymi i obłudnikami i bądź dla nich surowy. Ich schronieniem jest Piekło, a jakże to złe przeznaczenie! 9:73; 66:9
- = I mówią: "Kiedy to przyjdzie to obietnica, jeśli jesteście prawdomówni?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = I posłaliśmy Mojżesza z Naszymi znakami i wyraźną władzą. 11:96; 40:23
- = I daliśmy Mojżeszowi Księgę, ale wzbudziła spory. I gdyby nie słowo, które wcześniej wyszło od twego Pana, zostałoby między nimi rozstrzygnięte. I zaprawdę, oni są w głębokiej wątpliwości co do niej. 11:110; 41:45
- = To nie jest trudne dla Allaha. 14:20; 35:17
- = "A kiedy go ukształtuję i tchnę w niego z mego ducha, padnijcie przed nim na twarz." 15:29; 38:72
- = I aniołowie wszyscy razem upadli na twarz. 15:30; 38:73
- = (Allah) powiedział: "Wyjdź z niego, bo jesteś przeklęty." 15:34; 38:77
- = (Iblis) powiedział: "Panie mój, daj mi więc zwłokę do Dnia, kiedy zostaną wskrzeszeni." 15:36; 38:79
- = (Allah) powiedział: "Zaprawdę, jesteś wśród tych, którzy mają zwłokę." 15:37; 38:80
- = Do Dnia określonego czasu." 15:38; 38:81
- = Z wyjątkiem Twoich szczerych sług wśród nich. 15:40; 38:83
- = Zaprawdę, bogobojni będą w ogrodach i wśród źródeł. 15:45; 51:15
- = (Abraham) powiedział: "Jakie jest więc wasze zadanie, o wysłańcy?" 15:57; 51:31
- = Powiedzieli: "Zostaliśmy wysłani do ludu przestępców." 15:58; 51:32
- = Ci, którzy uwierzyli i nie zmieszali swojej wiary z niesprawiedliwością – oni mają bezpieczeństwo i oni są prowadzeni. 16:42; 29:59
- = Aby zaprzeczyli temu, co im daliśmy. Używajcie więc, a wkrótce się dowiecie. 16:55; 30:34
- = Potem podążył drogą. 18:89; 18:92
- = Idź do Faraona, gdyż on przekroczył granice. 20:24; 79:17
- = I ci, którzy strzegą swoich części intymnych. 23:5; 70:29
- = Z wyjątkiem swoich żon lub tego, co posiadły ich prawice – wtedy nie są nagannymi. 23:6; 70:30
- = A kto szuka ponad to, ci są przekraczającymi granice. 23:7; 70:31
- = I ci, którzy dotrzymują powierzonych im rzeczy i swoich przymierzy. 23:8; 70:32
- = (Noe) powiedział: "Panie mój, pomóż mi, bo oni mnie okłamali." 23:26; 23:39
- = Ta, Sin, Mim. 26:1; 28:1
- = To są wersety Księgi jasnej. 26:2; 28:2
- = Zaprawdę, w tym jest znak, lecz większość z nich nie wierzy. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = I zaprawdę, twój Pan – On jest Potężny, Litościwy. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = I potopiliśmy innych. 26:66; 37:82
- = Zaprawdę, jestem dla was godnym zaufania posłańcem. 26:107; 26:125; 26:143; 26:162; 26:178
- = Bójcie się więc Allaha i bądźcie mi posłuszni. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = I nie żądam od was za to żadnej nagrody; moja nagroda jest tylko u Pana światów. 26:109; 26:127; 26:145; 26:164; 26:180
- = W ogrodach i wśród źródeł. 26:147; 44:52
- = Powiedzieli: "Jesteś tylko jednym z oczarowanych." 26:153; 26:185
- = Z wyjątkiem jego żony – przeznaczyliśmy, że będzie wśród tych, którzy pozostaną. 26:171; 37:135
- = Potem zniszczyliśmy innych. 26:172; 37:136
- = I spuściliśmy na nich deszcz (kamieni), i jakże zły był deszcz dla ostrzeżonych! 26:173; 27:58
- = Czy oni chcą przyspieszyć karę? 26:204; 37:176
- = Ci, którzy odprawiają modlitwę, dają jałmużnę i są pewni życia ostatecznego. 27:3; 31:4
- = I (pamiętaj) Dnia, kiedy On ich wezwie i powie: "Gdzie są moi 'towarzysze', których głosiliście?" 28:62; 28:74
- = I nasi przodkowie? 37:17; 56:48
- = I będą zbliżać się do siebie, wypytując. 37:27; 52:25
- = Z wyjątkiem szczerych sług Allaha. 37:40; 37:74; 37:128; 37:160
- = W Ogrodach Rozkoszy. 37:43; 56:12
- = I pozostawiliśmy po nim (dobrą pamięć) wśród późniejszych pokoleń: 37:78; 37:108; 37:129
- = Tak oto nagradzamy dobroczyńców. 37:80; 37:121; 37:131; 77:44
- = Zaprawdę, on był wśród Naszych wiernych sług. 37:81; 37:111; 37:132
- = Co wam jest? Jak osądzacie? 37:154; 68:36
- = To (Koran) jest tylko napomnieniem dla światów. 38:87; 81:27
- = Objawienie Księgi pochodzi od Allaha, Potężnego, Mądrego. 39:1; 45:2; 46:2
- = Ha, Mim. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = Na Księgę jasną! 43:2; 44:2
- = Pozostaw ich więc, niech pogrążają się w pustej mowie i zabawie, aż spotkają swój Dzień, który im obiecano. 43:83; 70:42
- = (Zostanie im powiedziane): "Jedzcie i pijcie w zadowoleniu za to, co czyniliście." 52:19; 77:43
- = Czy żądasz od nich nagrody, a oni są obciążeni długami? 52:40; 68:46
- = Czy posiadają wiedzę o rzeczach ukrytych, więc zapisują? 52:41; 68:47
- = I jakże straszna była Moja kara i Moje ostrzeżenia! 54:16; 54:21; 54:30
- = I uczyniliśmy Koran łatwym do zapamiętania. Czy jest więc ktoś, kto by go pamiętał? 54:17; 54:22; 54:32; 54:40
- = Które więc z dobrodziejstw waszego Pana będziecie zaprzeczać? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = Wielka grupa wśród pierwszych. 56:13; 56:39
- = I (plonów) zostaliśmy pozbawieni? 56:67; 68:27
- = Wysławiaj więc imię twego Pana, Wielkiego! 56:74; 56:96; 69:52
- = To jest objawienie od Pana światów. 56:80; 69:43
- = Wszystko, co jest w niebiosach i na ziemi, wysławia Allaha, a On jest Potężny, Mądry. 59:1; 61:1
- = Kiedy recytuje się mu Nasze wersety, mówi: "To są bajki dawnych!" 68:15; 83:13
- = Wtedy będzie w przyjemnym życiu. 69:21; 101:7
- = W ogrodzie wyniosłym. 69:22; 88:10
