- A kiedy obdarzamy człowieka łaską, on się odwraca i oddala, a kiedy dotknie go zło. (وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَى بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ) 17:83; 41:51
